424	/** Builds the shared predicate list behind `listIssues` and its count. */
425	function issueFilters(input: IssueFilterInput): readonly SQL[] {
426	  const scope: ArchiveScope = shouldFilterArchived(input)
427	    ? {}
428	    : { includeArchived: true };
429	
430	  return compact(
431	    orgPredicate(issues.orgId, input.orgId),
432	    livePredicate(issues.archivedAt, scope),
433	    input.projectId === undefined
434	      ? undefined
435	      : eq(issues.projectId, input.projectId),
436	    input.status === undefined || input.status.length === 0
437	      ? undefined
438	      : inArray(issues.status, [...input.status]),
439	    input.priority === undefined || input.priority.length === 0
440	      ? undefined
441	      : inArray(issues.priority, [...input.priority]),
442	    input.assigneeId === undefined
443	      ? undefined
444	      : input.assigneeId === null
445	        ? isNull(issues.assigneeId)
446	        : eq(issues.assigneeId, input.assigneeId),
447	    input.authorId === undefined
448	      ? undefined
449	      : eq(issues.authorId, input.authorId),
450	    input.dueBefore === undefined ? undefined : lt(issues.dueAt, input.dueBefore),
451	    input.query === undefined
452	      ? undefined
453	      : or(
454	          like(issues.title, `%${input.query}%`),
455	          like(issues.description, `%${input.query}%`),
456	        ),
457	    input.labelIds === undefined || input.labelIds.length === 0
458	      ? undefined
459	      : inArray(
460	          issues.id,
461	          getDb()
462	            .select({ id: issueLabels.issueId })
463	            .from(issueLabels)
464	            .where(
465	              and(
466	                orgPredicate(issueLabels.orgId, input.orgId),
467	                inArray(issueLabels.labelId, [...input.labelIds]),
468	              ),
469	            ),
470	        ),
471	  );
472	}
