474	export async function listIssues(
475	  input: IssueFilterInput,
476	): Promise<Page<Issue>> {
477	  const db = getDb();
478	  const filters = issueFilters(input);
479	  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };
480	
481	  const total = db
482	    .select({ value: count() })
483	    .from(issues)
484	    .where(and(...filters))
485	    .get();
486	
487	  const rows = db
488	    .select()
489	    .from(issues)
490	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
491	    .orderBy(desc(issues.createdAt), desc(issues.id))
492	    .limit(probeLimit(input.limit))
493	    .all();
494	
495	  const labels = await listLabelsForIssues(
496	    input.orgId,
497	    rows.map((row) => row.id as IssueId),
498	  );
499	
500	  return toPage(
501	    rows,
502	    input.limit,
503	    total?.value ?? 0,
504	    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
505	    (row) => ({ id: row.id, sortValue: row.createdAt }),
506	  );
507	}
