509	/**
510	 * The list view needs comment and attachment counts per row. Two grouped
511	 * queries beat N+1 round trips, so the counts are folded in afterwards.
512	 */
513	export async function listIssuesWithRelations(
514	  input: IssueFilterInput,
515	): Promise<Page<IssueWithRelations>> {
516	  const db = getDb();
517	  const page = await listIssues(input);
518	  const ids = page.items.map((issue) => issue.id);
519	  if (ids.length === 0) {
520	    return { items: [], nextCursor: page.nextCursor, total: page.total };
521	  }
522	
523	  const commentCounts = db
524	    .select({ issueId: comments.issueId, value: count() })
525	    .from(comments)
526	    .where(
527	      and(
528	        orgPredicate(comments.orgId, input.orgId),
529	        inArray(comments.issueId, [...ids]),
530	        isNull(comments.archivedAt),
531	      ),
532	    )
533	    .groupBy(comments.issueId)
534	    .all();
535	
536	  const attachmentCounts = db
537	    .select({ issueId: attachments.issueId, value: count() })
538	    .from(attachments)
539	    .where(
540	      and(
541	        orgPredicate(attachments.orgId, input.orgId),
542	        inArray(attachments.issueId, [...ids]),
543	      ),
544	    )
545	    .groupBy(attachments.issueId)
546	    .all();
547	
548	  const labels = await listLabelsForIssues(input.orgId, ids);
549	  const commentsBy = new Map(commentCounts.map((r) => [r.issueId, r.value]));
550	  const attachmentsBy = new Map(
551	    attachmentCounts.map((r) => [r.issueId, r.value]),
552	  );
553	
554	  return {
555	    items: page.items.map((issue) => ({
556	      issue,
557	      labels: labels[issue.id] ?? [],
558	      commentCount: commentsBy.get(issue.id) ?? 0,
559	      attachmentCount: attachmentsBy.get(issue.id) ?? 0,
560	    })),
561	    nextCursor: page.nextCursor,
562	    total: page.total,
563	  };
564	}
