1076	export async function listThread(
1077	  orgId: OrgId,
1078	  issueId: IssueId,
1079	): Promise<readonly CommentThreadNode[]> {
1080	  const rows = getDb()
1081	    .select({ comment: comments, author: users })
1082	    .from(comments)
1083	    .innerJoin(users, eq(users.id, comments.authorId))
1084	    .where(
1085	      and(
1086	        orgPredicate(comments.orgId, orgId),
1087	        eq(comments.issueId, issueId),
1088	      ),
1089	    )
1090	    .orderBy(asc(comments.createdAt))
1091	    .all();
1092	
1093	  const decorated: CommentWithAuthor[] = rows.map((row) => ({
1094	    ...toComment(row.comment),
1095	    author: toUser(row.author),
