 * Union of the ids parsed out of the body server-side and the ones the
 * composer supplied. Both are held to the same rule: only current members of
 * the organization can be mentioned. Anything else — a stranger, a member of
 * another workspace, someone who has left — is dropped silently, so it is
 * neither stored nor notified and never fails the comment write.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const resolved = resolveMentions(body, await listAllMembers(orgId));

  const mentioned: UserId[] = [];
  for (const userId of new Set([...resolved, ...clientProvided])) {
    if (await isCurrentMember(orgId, userId)) mentioned.push(userId);
  }
  return mentioned;
}

/** Every live member of the org, walking the cursor so none are skipped. */
async function listAllMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const all: MemberWithUser[] = [];
  let cursor: string | null = null;

  do {
    const page: Awaited<ReturnType<typeof memberRepo.listMembers>> =
      await memberRepo.listMembers({
        orgId,
        limit: MENTION_LOOKUP_LIMIT,
        cursor,
      });
    all.push(...page.items);
    cursor = page.nextCursor;
  } while (cursor !== null);

  return all;
}
